/// Write a `PPr` as its element, `oac:pPr`.
#[must_use]
pub fn p_pr(node: &super::PPr, scope: &mut Scope) -> Element {
    let mut writer = crate::Writer::new(scope, &super::P_PR_SHAPE, &node.unknown);
    writer.attribute(0, &node.mar_l);
    writer.attribute(1, &node.mar_r);
    writer.attribute(2, &node.lvl);
    writer.attribute(3, &node.indent);
    writer.attribute(4, &node.algn);
    writer.attribute(5, &node.def_tab_sz);
    writer.attribute(6, &node.rtl);
    writer.attribute(7, &node.ea_ln_brk);
    writer.attribute(8, &node.font_algn);
    writer.attribute(9, &node.latin_ln_brk);
    writer.attribute(10, &node.hanging_punct);
    writer.child(&node.line_spacing);
    writer.child(&node.space_before);
    writer.child(&node.space_after);
    writer.child(&node.text_bullet_color_content);
    writer.child(&node.text_bullet_size_content);
    writer.child(&node.text_bullet_typeface_content);
    writer.child(&node.text_bullet_content);
    writer.child(&node.tab_list);
    writer.child(&node.default_text_run_properties);
    writer.child(&node.extension_list);
    writer.finish()
}

